    event.classResources &&
      event.classResources.forEach((resource) => {
        if (resource.type !== RESOURCE_TYPES.FURY.id) {
          return;
        }
        this.gained += MAX_FURY - (resource.amount - resource.cost);
        if (resource.amount >= 50) {
          this.badCast += 1;
